          'import { useMemo, useState } from "react";\nimport { Badge } from "@/components/ui/badge";\nimport { Button } from "@/components/ui/button";\nimport {\n  Card,\n  CardContent,\n  CardDescription,\n  CardHeader,\n  CardTitle,\n} from "@/components/ui/card";\nimport { Input } from "@/components/ui/input";\nimport { Separator } from "@/components/ui/separator";\nimport { useMiloState } from "@/milo";\nimport { contract } from "./contract";\n\ntype Dossier = NonNullable<\n  ReturnType<typeof useDossiers>["value"]\n>["days"][string][string];\n\nexport default function App() {\n  const dossiers = useDossiers();\n  const initial = useMemo(readLocation, []);\n  const [day, setDay] = useState(initial.day);\n  const [meetingId, setMeetingId] = useState<string | null>(initial.meetingId);\n  const meetings = Object.entries(dossiers.value?.days[day] ?? {}).sort(\n    ([, left], [, right]) => left.startsAt.localeCompare(right.startsAt),\n  );\n  const meeting =\n    meetingId === null ? undefined : dossiers.value?.days[day]?.[meetingId];\n\n  if (meeting !== undefined) {\n    return (\n      <main className="mx-auto grid max-w-3xl gap-5 p-6 md:p-10">\n        <Button\n          className="w-fit"\n          variant="ghost"\n          onClick={() => setMeetingId(null)}\n        >\n          Back to {day}\n        </Button>\n        <DossierView dossier={meeting} />\n      </main>\n    );\n  }\n\n  return (\n    <main className="mx-auto grid max-w-4xl gap-6 p-6 md:p-10">\n      <header className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">\n        <div>\n          <p className="text-sm text-muted-foreground">\n            Prepared context for the meetings that matter\n          </p>\n          <h1 className="text-2xl font-semibold tracking-tight">\n            Meeting prep\n          </h1>\n        </div>\n        <Input\n          aria-label="Meeting date"\n          className="w-auto"\n          type="date"\n          value={day}\n          onChange={(event) => setDay(event.target.value)}\n        />\n      </header>\n      {dossiers.status === "loading" ? (\n        <p className="text-sm text-muted-foreground">Loading dossiers…</p>\n      ) : meetings.length === 0 ? (\n        <Card>\n          <CardHeader>\n            <CardTitle>No meeting prep for this day</CardTitle>\n            <CardDescription>\n              Dossiers appear here when a meeting is worth preparing for.\n            </CardDescription>\n          </CardHeader>\n        </Card>\n      ) : (\n        <div className="grid gap-3">\n          {meetings.map(([id, dossier]) => (\n            <button\n              className="text-left"\n              key={id}\n              type="button"\n              onClick={() => setMeetingId(id)}\n            >\n              <Card className="transition-colors hover:bg-muted/40">\n                <CardHeader>\n                  <div className="flex items-start justify-between gap-4">\n                    <div>\n                      <CardDescription>\n                        {formatTime(dossier.startsAt)}\n                      </CardDescription>\n                      <CardTitle>{dossier.title}</CardTitle>\n                    </div>\n                    {isNext(dossier.startsAt, meetings) ? (\n                      <Badge variant="secondary">Next</Badge>\n                    ) : null}\n                  </div>\n                </CardHeader>\n                <CardContent className="text-muted-foreground">\n                  {dossier.attendees.map(attendeeName).join(", ") ||\n                    "No attendees listed"}\n                </CardContent>\n              </Card>\n            </button>\n          ))}\n        </div>\n      )}\n      {dossiers.error === null ? null : (\n        <p className="text-sm text-destructive">{dossiers.error.message}</p>\n      )}\n    </main>\n  );\n}\n\nfunction DossierView({ dossier }: { dossier: Dossier }) {\n  return (\n    <Card>\n      <CardHeader>\n        <CardDescription>\n          {formatDateTime(dossier.startsAt)} · Prepared{" "}\n          {formatDateTime(dossier.preparedAt)}\n        </CardDescription>\n        <CardTitle className="text-xl">{dossier.title}</CardTitle>\n      </CardHeader>\n      <CardContent className="grid gap-5">\n        <Section title="People">\n          <div className="grid gap-3">\n            {dossier.attendees.map((attendee) => (\n              <div key={attendee.email ?? attendee.name}>\n                <p className="font-medium">{attendee.name}</p>\n                <p className="text-sm text-muted-foreground">\n                  {[attendee.company, attendee.email]\n                    .filter(Boolean)\n                    .join(" · ")}\n                </p>\n                {attendee.notes ? (\n                  <p className="mt-1 text-sm">{attendee.notes}</p>\n                ) : null}\n              </div>\n            ))}\n          </div>\n        </Section>\n        <Section title="Context">\n          <p className="whitespace-pre-wrap text-sm leading-6">\n            {dossier.context}\n          </p>\n        </Section>\n        <Section title="Have ready">\n          <ul className="list-disc space-y-1 pl-5 text-sm">\n            {dossier.prepare.map((item) => (\n              <li key={item}>{item}</li>\n            ))}\n          </ul>\n        </Section>\n        {dossier.threads.length === 0 ? null : (\n          <Section title="Recent threads">\n            <div className="grid gap-3">\n              {dossier.threads.map((thread) => (\n                <div key={thread.subject}>\n                  <p className="font-medium">{thread.subject}</p>\n                  <p className="text-sm text-muted-foreground">\n                    {thread.takeaway}\n                  </p>\n                </div>\n              ))}\n            </div>\n          </Section>\n        )}\n      </CardContent>\n    </Card>\n  );\n}\n\nfunction Section({\n  children,\n  title,\n}: {\n  children: React.ReactNode;\n  title: string;\n}) {\n  return (\n    <section className="grid gap-3">\n      <Separator />\n      <h2 className="text-sm font-semibold">{title}</h2>\n      {children}\n    </section>\n  );\n}\n\nfunction useDossiers() {\n  return useMiloState(contract.state.dossiers);\n}\n\nfunction readLocation() {\n  const params = new URLSearchParams(window.location.hash.replace(/^#/, ""));\n  return {\n    day: params.get("d") ?? localDate(new Date()),\n    meetingId: params.get("m"),\n  };\n}\n\nfunction localDate(date: Date) {\n  const year = date.getFullYear();\n  const month = String(date.getMonth() + 1).padStart(2, "0");\n  const day = String(date.getDate()).padStart(2, "0");\n  return `${year}-${month}-${day}`;\n}\n\nfunction attendeeName(attendee: Dossier["attendees"][number]) {\n  return attendee.company\n    ? `${attendee.name} (${attendee.company})`\n    : attendee.name;\n}\n\nfunction formatTime(value: string) {\n  return new Intl.DateTimeFormat(undefined, {\n    hour: "2-digit",\n    minute: "2-digit",\n  }).format(new Date(value));\n}\n\nfunction formatDateTime(value: string) {\n  return new Intl.DateTimeFormat(undefined, {\n    dateStyle: "medium",\n    timeStyle: "short",\n  }).format(new Date(value));\n}\n\nfunction isNext(startsAt: string, meetings: Array<[string, Dossier]>) {\n  const now = Date.now();\n  return (\n    meetings.find(\n      ([, dossier]) => new Date(dossier.startsAt).getTime() >= now,\n    )?.[1].startsAt === startsAt\n  );\n}\n',
